mapper.select:
SELECT primary_key, source, contract_name, contract_number,contract_type,
buyer, seller, enterprise_code,customer_code,customer_contact,
user_code, language, payment_strategy, column_titles,
amount_title, product_detail,
state,contract_time,cancel_reason,sell_contract, data_version,business_belong
FROM  ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND delete_flag= 'f'
AND user_code = #{userCode}

    AND contract_number LIKE '%'|| #{contractNumber} ||'%'


    AND contract_time >= #{contractTimePreDate}


    AND contract_time <= #{contractTimePostDate}


    AND business_belong = #{businessBelong}

ORDER BY create_time DESC

SELECT primary_key, source, contract_name, contract_number,contract_type,
buyer, seller, enterprise_code,customer_code,customer_contact,
user_code, language, payment_strategy, column_titles,
amount_title, product_detail, clauses_chs, clauses_en,
state,contract_time, data_version,
sign_areas,sell_contract,sell_quotation,buyer_quotation,attachments, temp_data,business_belong,qrcode_generated_flag
FROM  ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND primary_key= #{contractCode}
AND user_code= #{userCode}

mapper.update:
UPDATE ${tableName}
SET temp_data = NULL
WHERE
    enterprise_code= #{model.ownedEnterpriseCode}
  AND primary_key = #{model.contractCode}
  AND temp_data IS NOT NULL

UPDATE ${tableName}
SET temp_data = #{model.tempData}
WHERE
    enterprise_code= #{model.ownedEnterpriseCode}
  AND primary_key = #{model.contractCode}

mapper.select:
SELECT COUNT(id)
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
AND primary_key != #{excludeContractCode}
AND contract_number = #{contractNumber}
AND delete_flag = 'f'

mapper.delete:
DELETE FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND primary_key = #{contractCode}
  AND data_version = #{clientDataVersion}

mapper.select:
SELECT primary_key, source, contract_name, contract_number,contract_type,
       buyer, seller, enterprise_code,customer_code,customer_contact,
       user_code, language, payment_strategy, column_titles,
    amount_title, product_detail, clauses_chs, clauses_en,
    state,contract_time, data_version,
    sign_areas,sell_contract,sell_quotation,buyer_quotation,attachments, temp_data
FROM  ${tableName}
WHERE
    enterprise_code= #{enterpriseCode}
  AND primary_key= #{contractCode}

mapper.update:
UPDATE ${tableName}
SET qrcode_generated_flag = #{qrcodeGeneratedFlag}
WHERE enterprise_code = #{enterpriseCode}
  AND primary_key = #{contractCode}

UPDATE ${tableName}
SET product_detail = #{model.productDetail},
    data_version   = #{model.dataVersion}
WHERE enterprise_code = #{model.ownedEnterpriseCode}
  AND primary_key = #{model.contractCode}

UPDATE ${tableName}
SET buyer           = #{model.buyer},
    contract_number = #{model.contractNumber},
    data_version    = #{model.dataVersion}
WHERE enterprise_code = #{model.ownedEnterpriseCode}
  AND primary_key = #{model.contractCode}
